/// Helper function to define a refinement test that can be instantiated for
/// the various types.
///
/// # Details
///
/// Internally requests a counter example to be generated, and checks that
/// the counter example is indeed a valid witness for the failure of the
/// refinement check.
fn is_refinement_test(
    dump_name: &str,
    rng: &mut StdRng,
    refinement: RefinementType,
    strategy: ExplorationStrategy,
    preprocess: bool,
) {
    let files = DumpFiles::new(dump_name);

    let spec_lts = random_lts::<String, _>(rng, 100, 3);
    let impl_lts = mutate_lts(&spec_lts, rng, 100).unwrap();

    files.dump("spec.aut", |w| write_aut(w, &spec_lts)).unwrap();
    files.dump("impl.aut", |w| write_aut(w, &impl_lts)).unwrap();

    let mut timing = Timing::default();
    let (result, counter_example) = refines(
        impl_lts.clone(),
        spec_lts.clone(),
        refinement,
        strategy,
        preprocess,
        true,
        &mut timing,
    );

    if !result {
        if let Some(ce) = counter_example {
            let formula = generate_refinement_formula(&ce);
            println!("Counter example formula: {}", formula);

            files
                .dump("counter_example.mcf", |f| Ok(writeln!(f, "{}", formula)?))
                .unwrap();

            // No `act` declarations: `formula` is built directly over the two LTSs' own string
            // labels, with a randomly-generated alphabet per run — there's nothing to declare it
            // against, so it type-checks as a "simple action" formula instead. `translate` desugars
            // and type checks its own copy, so each LTS needs one (weak-equivalence refinements can
            // generate `(tau)*`-style regular formulas, which `translate` desugars internally).
            let spec = UntypedStateFrmSpec {
                formula,
                action_declarations: Vec::new(),
                data_specification: UntypedDataSpecification::default(),
            };

            let impl_pg = translate(&impl_lts, spec.clone()).unwrap();
            let spec_pg = translate(&spec_lts, spec).unwrap();

            let (impl_solution, _) = solve_zielonka(&impl_pg, false);
            let (spec_solution, _) = solve_zielonka(&spec_pg, false);

            // The formula distinguishes the two systems iff their initial
            // vertices end up in different players' winning sets. Index the Even
            // winning set (player 0) by the initial vertex of each game.
            let impl_init = impl_pg.initial_vertex();
            let spec_init = spec_pg.initial_vertex();
            assert!(
                impl_solution[0][*impl_init] != spec_solution[0][*spec_init],
                "Refinement returned false, but the counter example is not distinguishing."
            );
        } else {
            panic!("Expected a counter example.");
        }
    }
}
